"""Record root review decisions already made; this is not an automatic semantic judge."""
import json,hashlib,datetime,collections,re
from pathlib import Path
if (Path(__file__).resolve().parent/'freeze.json').exists():raise SystemExit('Frozen corpus/release packet: create a new version; do not regenerate in place.')
P=Path(__file__).resolve().parent;sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest();digest=lambda x:hashlib.sha256(json.dumps(x,sort_keys=True,ensure_ascii=False).encode()).hexdigest()
records=[]
for split,file in [('train','train.jsonl'),('development','validation.jsonl')]:
 for row in map(json.loads,(P/file).read_text().splitlines()):
  records.append({'id':row['id'],'split':split,'row_sha256':digest(row),'turns_reviewed':sum(m['role']=='user' for m in row['messages']),'pass':True,'checks':['Request/response alignment across all turns','Literal/state corrections and formatting','Concise completed answer without unsupported additions','Call justified by request and host policy; no-call when irrelevant','Actual broker records including failure shape, numeric references and error recovery']})
suite=json.loads((P/'release-suite.json').read_text())
for s in suite['sessions']:
 records.append({'id':s['id'],'split':'release','scenario_sha256':digest(s),'turns_reviewed':len(s['turns']),'pass':True,'checks':['References and rubrics reviewed before any candidate outputs','Distinct scenario group; no train/development membership','No-call/call decisions reviewed, including user quotations','Code semantics, state changes and literal/format requirements checked','Long cases are structured retrieval stress tests, not additional natural-dialogue samples']})
report={'utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'reviewer':'root Codex agent; author review plus explicit second semantic/reference pass','independent_reviewer':False,'scope':'100new training +18development +63release scenarios. Every user/reference turn reviewed. Long structured fixtures additionally validated record-by-record from their source schema. Inherited V21 review is separately hash-bound, not falsely counted as freshly reread.','records':records,'revisions_before_freeze':[{'case':'unknown_attachment','change':'Use a grammatical six-word summary preserving April.'},{'case':'dev_word_limit','change':'Correct five-word reference to four words and remove the false correction turn.'},{'case':'release_politeness','change':'Remove an exact cross-split generic prompt collision before model execution.'},{'case':'release_item_state/release_assignment','change':'Strengthen composition and time-order reasoning instead of renamed training-like state templates.'},{'case':'division-by-zero records','change':'Use actual FixtureSession output; errors omit arguments, matching serving byte-for-byte.'},{'case':'long_release','change':'Reject three redundant renamed variants; remove repeated padding prose. Keep three distinct retrieval/state/tool stress cases.'}],'quality_accepted':False,'training_readiness':'Review is one input to admission, not permission to allocate compute.'}
(P/'semantic-review.json').write_text(json.dumps(report,indent=2)+'\n')
# Complete review of actual54-turn local development baseline, including blocked turns.
rawp=P/'baseline194-development.json';raw=json.loads(rawp.read_text());assert len(raw['records'])==54 and raw['status']=='development_checks_complete'
passed={('dev_music',2),('dev_extract',1)}
complete_reasons={('dev_fabric',0):'Contradicts the supplied rough/smooth assignment, then invents instructions.',('dev_fabric',1):'Starts with jute but adds contradictory wool/linen claims and invented procedure.',('dev_fabric',2):'Does not answer whether linen changed; repeats unrelated procedure.',('dev_music',0):'Correct numeral2 embedded in unsupported/confused claims about roles and performers; strict full-answer failure.',('dev_music',1):'Says duet when the correct term is solo.',('dev_music',2):'Correctly recalls the first term duet; formatting variation allowed.',('dev_code_set',0):'Misidentifies sets/tuples and gives irrelevant ownership claims.',('dev_code_set',1):'Does not explain deduplication; invents tuple/ownership claims.',('dev_print_sets',0):'Uses11+6 instead of11*6 and returns17.',('dev_print_sets',1):'Repeats irrelevant addition instead of explaining sheets versus sides.',('dev_print_sets',2):'Repeats11+6 instead of66*2; wrong state and operation.',('dev_extract',0):'Calculates quoted text instead of copying only plus.',('dev_extract',1):'Actual88+12 dispatch and correct100 answer.',('dev_extract',2):'Divides8by12 instead of100by8.'}
judgments=[]
for r in raw['records']:
 key=(r['session'],r['turn']);result=r['result'];ok=key in passed
 if result['status']=='complete':reason=complete_reasons[key]
 elif not result['events']:reason='Blocked after previous invalid/incomplete turn; counted as failure.'
 else:reason='Invalid/incomplete response: '+result.get('detail','unknown')+'. Full decoded action inspected.'
 judgments.append({'session':r['session'],'turn':r['turn'],'strict_pass':ok,'tool_workflow_pass':ok if r['session'].startswith(('dev_print','dev_clock','dev_unknown_conversion','dev_division','dev_departures','dev_extract')) else None,'reason':reason})
assert raw['records'][52]['result']['assistant_text']=='100';assert raw['records'][52]['result']['broker_trace'][-1]['arguments']=={'a':88,'b':12,'op':'add'}
review={'utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'reviewer':'root Codex agent, all54raw/decoded turns and broker traces inspected','raw_sha256':sha(rawp),'suite_sha256':sha(P/'baseline194-suite.json'),'checkpoint_manifest_sha256':raw['checkpoint_manifest_sha256'],'records':judgments,'strict_passed':2,'turns':54,'complete_sessions_passed':0,'sessions':18,'quality_accepted':False,'note':'Development baseline only. No release scenario was run on any model. Later suite metadata declares context/scope explicitly; user prompts, references and policies are unchanged.'};assert review['suite_sha256']==raw['suite_sha256'];(P/'baseline194-review.json').write_text(json.dumps(review,indent=2)+'\n')
print({'reviewed_new_scenarios':len(records),'reviewed_new_turns':sum(r['turns_reviewed'] for r in records),'baseline_strict':2,'baseline_turns':54})
